<template>
  <div class="pcal-root">
    <div v-if="loading" class="pcal-loading">
      <v-progress-circular indeterminate color="#6366f1" size="24" width="2" />
    </div>

    <template v-else-if="windows.length">
      <div class="pcal-header">
        <div class="pcal-header__left">
          <v-icon size="15" color="#6366f1">mdi-calendar-clock</v-icon>
          <span class="pcal-header__title">Performance Calendar</span>
          <span class="pcal-header__fy">FY {{ currentFiscalYear }}</span>
        </div>
        <span v-if="activeWindows.length" class="pcal-header__live">
          <span class="pcal-live-dot"></span>
          {{ activeWindows.length }} window{{
            activeWindows.length > 1 ? "s" : ""
          }}
          open
        </span>
      </div>

      <!-- Timeline strip -->
      <div class="pcal-timeline">
        <div class="pcal-timeline__months">
          <div v-for="m in MONTHS" :key="m.num" class="pcal-timeline__month">
            {{ m.short }}
          </div>
        </div>
        <div class="pcal-timeline__track">
          <div
            class="pcal-timeline__today"
            :style="{ left: todayFraction * 100 + '%' }"
          >
            <div class="pcal-timeline__today-line"></div>
            <div class="pcal-timeline__today-label">Today</div>
          </div>
          <div
            v-for="win in timelineWindows"
            :key="win.key"
            class="pcal-timeline__band"
            :style="win.bandStyle"
          >
            <span class="pcal-timeline__band-label">{{ win.short }}</span>
          </div>
        </div>
      </div>

      <!-- Action window rows -->
      <div class="pcal-windows">
        <div
          v-for="win in actionWindows"
          :key="win.key"
          class="pcal-row"
          :class="{
            'pcal-row--active': win.status === 'active',
            'pcal-row--upcoming': win.status === 'upcoming',
          }"
          :style="{ '--accent': win.color, '--accent-rgb': win.colorRgb }"
        >
          <div class="pcal-row__left">
            <div
              class="pcal-row__icon-wrap"
              :class="'pcal-row__icon-wrap--' + win.status"
            >
              <v-icon
                size="14"
                :color="win.status === 'active' ? '#fff' : win.color"
                >{{ win.icon }}</v-icon
              >
            </div>
            <div>
              <div
                class="pcal-row__name"
                :class="{ 'pcal-row__name--active': win.status === 'active' }"
              >
                {{ win.label }}
              </div>
              <span
                v-if="win.context"
                class="pcal-context-tag"
                :class="'pcal-context-tag--' + win.context"
              >
                {{ contextLabel(win.context) }}
              </span>
            </div>
          </div>

          <div class="pcal-row__dates">
            <span class="pcal-row__date">{{
              mmddToMonthDay(win.startDate)
            }}</span>
            <v-icon size="11" color="#a8a29e">mdi-arrow-right</v-icon>
            <span class="pcal-row__date">{{
              mmddToMonthDay(win.endDate)
            }}</span>
          </div>

          <div class="pcal-row__right">
            <!-- Override chip -->
            <span v-if="win.override" class="pcal-override-chip">
              <v-icon size="9">mdi-clock-fast</v-icon>
              Ext. {{ formatOverrideEnd(win.override.overrideEnd) }}
            </span>
            <span class="pcal-status" :class="'pcal-status--' + win.status">
              <span class="pcal-status__dot"></span>
              {{
                { active: "Open", upcoming: "Upcoming", closed: "Closed" }[
                  win.status
                ]
              }}
            </span>
          </div>
        </div>
      </div>
    </template>
  </div>
</template>

<script>
const MONTHS = [
  { num: 1, short: "Jan", days: 31 },
  { num: 2, short: "Feb", days: 28 },
  { num: 3, short: "Mar", days: 31 },
  { num: 4, short: "Apr", days: 30 },
  { num: 5, short: "May", days: 31 },
  { num: 6, short: "Jun", days: 30 },
  { num: 7, short: "Jul", days: 31 },
  { num: 8, short: "Aug", days: 31 },
  { num: 9, short: "Sep", days: 30 },
  { num: 10, short: "Oct", days: 31 },
  { num: 11, short: "Nov", days: 30 },
  { num: 12, short: "Dec", days: 31 },
];

const WINDOW_META = {
  "semester-1": {
    label: "Semester 1",
    icon: "mdi-numeric-1-circle-outline",
    color: "#4f46e5",
    colorRgb: "79,70,229",
    short: "S1",
    action: false,
  },
  "semester-2": {
    label: "Semester 2",
    icon: "mdi-numeric-2-circle-outline",
    color: "#0369a1",
    colorRgb: "3,105,161",
    short: "S2",
    action: false,
  },
  "goal-settings": {
    label: "Goal Setting",
    icon: "mdi-target",
    color: "#b45309",
    colorRgb: "180,83,9",
    short: "GS",
    action: true,
  },
  "mid-year-review": {
    label: "Mid-Year Review",
    icon: "mdi-calendar-edit",
    color: "#6d28d9",
    colorRgb: "109,40,217",
    short: "MR",
    action: true,
  },
  "year-end-review": {
    label: "Year-End Review",
    icon: "mdi-calendar-check",
    color: "#047857",
    colorRgb: "4,120,87",
    short: "YE",
    action: true,
  },
  appeals: {
    label: "Appeals",
    icon: "mdi-gavel",
    color: "#b91c1c",
    colorRgb: "185,28,28",
    short: "AP",
    action: true,
  },
  finalization: {
    label: "Finalization",
    icon: "mdi-check-all",
    color: "#0f766e",
    colorRgb: "15,118,110",
    short: "FN",
    action: true,
  },
};

export default {
  name: "PerformanceCalendar",
  data() {
    return { MONTHS, loading: true, windows: [], overrides: {} };
  },

  computed: {
    currentFiscalYear() {
      const now = new Date(),
        m = now.getMonth() + 1,
        y = now.getFullYear();
      return m >= 4 ? y : y - 1;
    },
    todayFraction() {
      const now = new Date();
      return this.mmddToFraction(
        String(now.getMonth() + 1).padStart(2, "0") +
          "-" +
          String(now.getDate()).padStart(2, "0"),
      );
    },
    actionWindows() {
      return this.windows.filter((w) => WINDOW_META[w.key]?.action);
    },
    activeWindows() {
      return this.windows.filter((w) => w.status === "active");
    },
    timelineWindows() {
      return this.windows
        .filter(
          (w) => this.isValidMmDd(w.startDate) && this.isValidMmDd(w.endDate),
        )
        .map((w, i) => {
          const l = this.mmddToFraction(w.startDate),
            r = this.mmddToFraction(w.endDate);
          const wraps = r < l,
            width = wraps ? 1 - l + r : r - l;
          const alpha =
            w.status === "active"
              ? "ff"
              : w.status === "upcoming"
              ? "cc"
              : "88";
          return {
            ...w,
            bandStyle: {
              left: (l * 100).toFixed(2) + "%",
              width: Math.max(width * 100, 1).toFixed(2) + "%",
              background: w.color + alpha,
              top: i * 20 + "px",
              border:
                w.status === "active"
                  ? "2px solid " + w.color
                  : "2px solid transparent",
            },
          };
        });
    },
  },

  async mounted() {
    await Promise.all([this.loadConfig(), this.loadOverrides()]);
  },

  methods: {
    async loadConfig() {
      try {
        const r = await fetch("/fhir/Parameters/performance-config");
        if (!r.ok) throw new Error();
        this.windows = this.parseResource(await r.json());
      } catch (err) {
        console.log(err);
      } finally {
        this.loading = false;
      }
    },
    async loadOverrides() {
      try {
        const r = await fetch("/fhir/Parameters/performance-override-config");
        if (!r.ok || r.status === 404) return;
        const resource = await r.json();
        for (const p of resource.parameter || []) {
          const get = (n) => {
            const x = (p.part || []).find((pt) => pt.name === n);
            return x?.valueString || "";
          };
          this.overrides[p.name] = {
            fiscalYear: get("fiscal-year"),
            overrideEnd: get("override-end"),
            status: get("status"),
          };
        }
      } catch (err) {
        console.log(err);
      }
    },
    parseResource(resource) {
      return (resource.parameter || [])
        .map((p) => {
          const meta = WINDOW_META[p.name];
          if (!meta) return null;
          const get = (n) => {
            const x = (p.part || []).find((pt) => pt.name === n);
            return x?.valueString || x?.valueDate || "";
          };
          const startDate = get("start-date"),
            endDate = get("end-date");
          const status = this.calcStatus(startDate, endDate);
          const override = this.getActiveOverride(p.name);
          const effectiveStatus = override
            ? this.calcOverrideStatus(override, status)
            : status;
          return {
            key: p.name,
            ...meta,
            startDate,
            endDate,
            context: this.deriveFiscalYearContext(p.name, startDate),
            status: effectiveStatus,
            override,
          };
        })
        .filter(Boolean);
    },
    getActiveOverride(key) {
      const ov = this.overrides[key];
      if (!ov || ov.status !== "active") return null;
      if (ov.overrideEnd && new Date(ov.overrideEnd) < new Date()) return null;
      return ov;
    },
    calcOverrideStatus(override, baseStatus) {
      // If base is closed but override is active and not expired, mark as active
      return baseStatus === "closed" ? "active" : baseStatus;
    },
    formatOverrideEnd(d) {
      if (!d) return "—";
      return new Date(d).toLocaleDateString("en-GB", {
        day: "numeric",
        month: "short",
      });
    },
    deriveFiscalYearContext(key, startDate) {
      if (key === "semester-1" || key === "semester-2") return null;
      if (!this.isValidMmDd(startDate)) return null;
      if (key === "mid-year-review") return "current";
      const inS1 = this.inSemester1(startDate);
      if (key === "goal-settings") return inS1 ? "current" : "next";
      return inS1 ? "previous" : "current";
    },
    contextLabel(c) {
      return (
        {
          next: "Next Year",
          current: "Current Year",
          previous: "Previous Year",
        }[c] || ""
      );
    },
    calcStatus(start, end) {
      if (!this.isValidMmDd(start) || !this.isValidMmDd(end)) return "closed";
      const now = new Date(),
        today = this.mmddToFraction(
          String(now.getMonth() + 1).padStart(2, "0") +
            "-" +
            String(now.getDate()).padStart(2, "0"),
        );
      const s = this.mmddToFraction(start),
        e = this.mmddToFraction(end),
        wraps = e < s;
      const active = wraps
        ? today >= s || today <= e
        : today >= s && today <= e;
      if (active) return "active";
      return (!wraps && today < s) || (wraps && today > e && today < s)
        ? "upcoming"
        : "closed";
    },
    mmMonth(mmdd) {
      return this.isValidMmDd(mmdd) ? parseInt(mmdd.split("-")[0]) : null;
    },
    inSemester1(mmdd) {
      const m = this.mmMonth(mmdd);
      return m !== null && m >= 4 && m <= 9;
    },
    isValidMmDd(val) {
      if (!val || typeof val !== "string" || !/^\d{2}-\d{2}$/.test(val))
        return false;
      const [mm, dd] = val.split("-").map(Number);
      return mm >= 1 && mm <= 12 && dd >= 1 && dd <= 31;
    },
    mmddToMonthDay(val) {
      if (!this.isValidMmDd(val)) return "—";
      const [mm, dd] = val.split("-").map(Number);
      return `${MONTHS[mm - 1].short} ${dd}`;
    },
    mmddToFraction(val) {
      if (!this.isValidMmDd(val)) return 0;
      const [mm, dd] = val.split("-").map(Number);
      return (
        (MONTHS.slice(0, mm - 1).reduce((s, m) => s + m.days, 0) + dd - 1) / 365
      );
    },
  },
};
</script>

